import Link from "next/link";
import { Check, Crown } from "lucide-react";
import { auth } from "@/auth";
import { readEntitlements } from "@/lib/entitlements";
import { PLANS } from "@/lib/plans";
import { PLAN_COMPARISON_ROWS } from "@/lib/plan-features";
import { localizedPrice, type PriceSearchParams } from "@/lib/localized-price";
import { Button } from "@/components/ui/button";
import { PricingCards } from "@/components/pricing/pricing-cards";
import { CheckoutButton } from "@/components/pricing/checkout-button";
import styles from "./PricingPage.module.css";
import { cn } from "@/lib/utils";

const tableCell =
  "[font-family:var(--font-plus-jakarta),system-ui,sans-serif]! mono:[font-family:inherit]! normal-case! tracking-normal! py-[13px]! px-5! text-left text-[14px]! border-b border-dotted border-separator align-top";

// Public copy derives its limits from the same config used by server enforcement.
// Rollout allowances remain visible in the authenticated workspace.
const PRICING = {
  groups: [
    {
      name: "Sending",
      features: [
        "Monthly emails",
        "Emails per UTC day",
        "Recipients per campaign",
        "PDF attachment",
        "Manual repeat sends",
      ],
    },
    {
      name: "Templates and contacts",
      features: [
        "Saved templates",
        "CSV import",
        "Re-add previously emailed contacts",
        "Add to shortlist directly from History",
        "Contact job roles",
        "Edit recipient roles in Compose",
        "Saved role shortcuts",
      ],
    },
    {
      name: "Tracking",
      features: [
        "Gmail acceptance status",
        "Mark replied button",
        "Follow-up reminders",
      ],
    },
    {
      name: "Look and support",
      features: ["Themes", "Preview highlight colors", "Priority support"],
    },
  ].map((group) => ({
    name: group.name,
    rows: group.features.map((label) =>
      PLAN_COMPARISON_ROWS.find((row) => row[0] === label)!,
    ),
  })),
  fine: [
    {
      title: "Allowances and resets",
      paragraphs: [
        "Daily allowances reset at midnight UTC.",
        "Free monthly allowances reset on the first day of each UTC calendar month; Premium monthly allowances follow the verified subscription billing period.",
        "Queued emails reserve capacity. Manually sent follow-up emails also use allowances.",
        "Unused emails do not roll over.",
      ],
    },
    {
      title: "Sending and reminders",
      paragraphs: [
        "Mailloop shows whether Gmail accepted each email. Acceptance does not guarantee delivery to a recipient’s inbox.",
        "Each email gets one sending attempt; failed emails are not automatically sent again.",
        "Mailloop never reads your inbox and cannot detect replies itself.",
        "Premium users use Mark replied, which stops reminders for that contact. Otherwise reminders use elapsed days since sending (3, 7, or 14).",
        "You decide whom to follow up with and approve each message; reminders never send automatically.",
      ],
    },
    {
      title: "Billing and cancellation",
      paragraphs: [
        "Premium renews monthly. Cancel at period end in Settings; verified Premium access continues through the current period.",
        "A cancellation request remains pending until verified. If a renewal fails, access continues only through a verified grace deadline shown in Settings.",
        "No refunds, except where required by applicable law.",
      ],
    },
    {
      title: "Support",
      paragraphs: [
        "Premium email requests are prioritized at [REDACTED_EMAIL].",
        "No guaranteed response time or 24/7 support is offered.",
      ],
    },
  ],
} as const;

function Value({ value }: { value: string | number }) {
  const unavailable = value === "Unavailable";
  const Icon = unavailable ? Crown : Check;
  return (
    <>
      <Icon
        className={
          unavailable
            ? `flex-none w-3.5 h-3.5 mt-[3px] text-[var(--pricing-muted)] premium-icon`
            : `flex-none w-4 h-4 p-[3px] rounded-[50%] [background:var(--pricing-check)] text-[var(--pricing-on-accent)] [stroke-width:3] mt-0.5`
        }
        aria-hidden="true"
      />
      <span>{unavailable ? "Not included" : value}</span>
    </>
  );
}

export default async function PricingPage({
  searchParams,
  signInAction,
}: {
  searchParams: PriceSearchParams;
  signInAction: () => Promise<void>;
}) {
  const [session, price] = await Promise.all([
    auth(),
    localizedPrice(searchParams),
  ]);
  const access = session?.user?.id
    ? await readEntitlements(session.user.id)
    : null;
  const currentPlan =
    access?.effectivePlan ?? (session?.user?.id ? "FREE" : null);

  return (
    <div className={`${styles.body} w-full min-w-0 text-[var(--pricing-text)]`}>
      <header className="text-center pt-16 pb-9 [@media(max-width:759px)]:pt-11">
        <h1 className="[font-family:inherit] font-extrabold text-[clamp(36px,5vw,60px)] leading-[1.08] tracking-[-0.04em] max-w-[16em] my-0 mx-auto">
          Simple{" "}
          <em className="not-italic text-[var(--pricing-accent)] mono:text-inherit">
            pricing
          </em>{" "}
          for <br />
          serious outreach.
        </h1>
        <p className="max-w-[34em] mt-4.5 mx-auto mb-0 text-[var(--pricing-muted)] text-[16px]">
          Start free with {PLANS.FREE.monthlyEmails} emails a month. Upgrade to
          Premium when you need more volume, reminders and CSV import.
        </p>
      </header>

      <PricingCards
        price={price}
        currentPlan={currentPlan}
        freeAction={
          currentPlan === "FREE" ? (
            <Button variant="outline" disabled>
              Current plan
            </Button>
          ) : currentPlan ? (
            <Button asChild variant="outline">
              <Link href="/compose">Open workspace</Link>
            </Button>
          ) : (
            <form action={signInAction}>
              <Button type="submit" variant="outline">
                Start free
              </Button>
            </form>
          )
        }
        premiumAction={
          currentPlan === "PAID" ? (
            <Button variant="outline" disabled>
              Current plan
            </Button>
          ) : (
            <CheckoutButton signedIn={Boolean(session?.user?.id)} />
          )
        }
      />
      <p className="max-w-220 [margin:22px_auto_0] text-center text-[var(--pricing-muted)] text-[13px]">
        Billing country determines eligibility. Hosted checkout shows the final
        quote, currency and taxes before you approve payment.
      </p>

      <section
        id="compare"
        className={`mt-18 [scroll-margin-top:24px]`}
        aria-labelledby="comparison-title"
      >
        <h2
          className="m-0 mb-1.5 [font-family:inherit] text-[clamp(30px,4.5vw,42px)] leading-[1.1] font-extrabold tracking-[-0.035em]"
          id="comparison-title"
        >
          Compare plans
        </h2>
        <p className="[margin:0_0_22px] text-[var(--pricing-muted)]">
          Every limit and feature, side by side.
        </p>
        <div
          className="max-w-full overflow-x-auto [background:var(--pricing-panel)] [border:1px_solid_var(--pricing-line)] rounded-[20px] shadow-[0_1px_2px_var(--pricing-shadow),_0_12px_32px_-16px_var(--pricing-shadow)]"
          tabIndex={0}
          role="region"
          aria-label="Scrollable plan comparison"
        >
          <table className="w-full min-w-[620px]! border-collapse">
            <caption className="sr-only">
              Free and Premium plan comparison
            </caption>
            <thead>
              <tr>
                <th
                  className={cn(
                    tableCell,
                    "bg-[var(--pricing-panel2)] text-[var(--pricing-muted)] text-[13px]! font-semibold!",
                  )}
                  scope="col"
                >
                  Feature
                </th>
                <th
                  className={cn(
                    tableCell,
                    "bg-[var(--pricing-panel2)] text-[var(--pricing-muted)] text-[13px]! font-semibold!",
                  )}
                  scope="col"
                >
                  Free
                </th>
                <th
                  className={cn(
                    tableCell,
                    "bg-[var(--pricing-panel2)] text-[var(--pricing-muted)] text-[13px]! font-semibold!",
                  )}
                  scope="col"
                >
                  Premium
                </th>
              </tr>
            </thead>
            {PRICING.groups.map((group) => (
              <tbody key={group.name}>
                <tr>
                  <th
                    className={cn(
                      tableCell,
                      "py-[9px]! bg-[var(--pricing-panel2)] text-[var(--pricing-link)] mono:text-[var(--pricing-muted)] text-[12.5px]! font-bold!",
                    )}
                    colSpan={3}
                    scope="rowgroup"
                  >
                    {group.name}
                  </th>
                </tr>
                {group.rows.map(([label, free, premium]) => (
                  <tr key={label}>
                    <th
                      className={cn(
                        tableCell,
                        "w-[38%] font-semibold! text-[var(--pricing-text)]",
                      )}
                      scope="row"
                    >
                      {label}
                    </th>
                    {[free, premium].map((value, index) => (
                      <td className={tableCell} key={index}>
                        <span
                          className={`inline-flex items-start gap-2 ${value === "Unavailable" ? "text-[var(--pricing-muted)]" : ""}`}
                        >
                          <Value value={value} />
                        </span>
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            ))}
          </table>
        </div>
      </section>

      <section
        className={`mt-18 [scroll-margin-top:24px]`}
        aria-labelledby="fine-print-title"
      >
        <h2
          className="m-0 mb-1.5 [font-family:inherit] text-[clamp(30px,4.5vw,42px)] leading-[1.1] font-extrabold tracking-[-0.035em]"
          id="fine-print-title"
        >
          The fine print, made readable
        </h2>
        <p className="[margin:0_0_22px] text-[var(--pricing-muted)]">
          How allowances, tracking and billing work.
        </p>
        <div className="grid grid-cols-[repeat(2,_minmax(0,_1fr))] gap-4 [@media(max-width:_759px)]:grid-cols-[1fr]">
          {PRICING.fine.map(({ title, paragraphs }) => (
            <article
              className={`${styles.fineCard} min-w-0 py-5.5 px-6 [border:1px_solid_var(--pricing-line)] rounded-[18px] [background:var(--pricing-panel)]`}
              key={title}
            >
              <h3 className="m-0 mb-2.5 text-[16px] font-bold">{title}</h3>
              {paragraphs.map((p) => (
                <p
                  key={p}
                  className="m-0 mb-[9px] last:mb-0 text-[var(--pricing-muted)] text-[14px] [overflow-wrap:anywhere]"
                >
                  {p.includes("[REDACTED_EMAIL]") ? (
                    <>
                      {p.split("[REDACTED_EMAIL]")[0]}
                      <a
                        className="text-[var(--pricing-link)] font-semibold"
                        href="mailto:[REDACTED_EMAIL]"
                      >
                        [REDACTED_EMAIL]
                      </a>
                      {p.split("[REDACTED_EMAIL]")[1]}
                    </>
                  ) : p === "Unused emails do not roll over." ||
                    p.startsWith("No refunds,") ? (
                    <strong className="text-[var(--pricing-text)]">{p}</strong>
                  ) : (
                    p
                  )}
                </p>
              ))}
            </article>
          ))}
        </div>
      </section>
      <p className="[margin:40px_0_0] text-center text-[var(--pricing-muted)] text-[12.5px]">
        Your workspace shows the allowances currently enforced during rollout.
      </p>
    </div>
  );
}
